          combined=[...(users.results||[]),...(pages.results||[])].sort((a,b)=>Number(b.recommendation_score)-Number(a.recommendation_score)||Number(b.follower_count)-Number(a.follower_count)||String(a.username).localeCompare(String(b.username))).slice(0,3);
